IF DB_ID(N'analysis') IS NULL EXEC(N'CREATE DATABASE analysis');
GO
USE analysis;
GO

IF OBJECT_ID(N'dbo.review', N'U') IS NOT NULL DROP TABLE dbo.review;
IF OBJECT_ID(N'dbo.productinventory', N'U') IS NOT NULL DROP TABLE dbo.productinventory;
IF OBJECT_ID(N'dbo.orderproduct', N'U') IS NOT NULL DROP TABLE dbo.orderproduct;
IF OBJECT_ID(N'dbo.incart', N'U') IS NOT NULL DROP TABLE dbo.incart;
IF OBJECT_ID(N'dbo.product', N'U') IS NOT NULL DROP TABLE dbo.product;
IF OBJECT_ID(N'dbo.category', N'U') IS NOT NULL DROP TABLE dbo.category;
IF OBJECT_ID(N'dbo.ordersummary', N'U') IS NOT NULL DROP TABLE dbo.ordersummary;
IF OBJECT_ID(N'dbo.shipment', N'U') IS NOT NULL DROP TABLE dbo.shipment;
IF OBJECT_ID(N'dbo.warehouse', N'U') IS NOT NULL DROP TABLE dbo.warehouse;
IF OBJECT_ID(N'dbo.paymentmethod', N'U') IS NOT NULL DROP TABLE dbo.paymentmethod;
IF OBJECT_ID(N'dbo.customer', N'U') IS NOT NULL DROP TABLE dbo.customer;
GO

CREATE TABLE customer (
    customerId          INT IDENTITY(1,1),
    firstName           VARCHAR(40),
    lastName            VARCHAR(40),
    email               VARCHAR(50),
    phonenum            VARCHAR(20),
    address             VARCHAR(50),
    city                VARCHAR(40),
    state               VARCHAR(20),
    postalCode          VARCHAR(20),
    country             VARCHAR(40),
    userid              VARCHAR(20),
    password            VARCHAR(30),
    PRIMARY KEY (customerId)
);

CREATE TABLE paymentmethod (
    paymentMethodId     INT IDENTITY(1,1),
    paymentType         VARCHAR(20),
    paymentNumber       VARCHAR(30),
    paymentExpiryDate   DATE,
    customerId          INT,
    PRIMARY KEY (paymentMethodId),
    FOREIGN KEY (customerId) REFERENCES customer(customerid)
        ON UPDATE CASCADE ON DELETE CASCADE 
);

CREATE TABLE warehouse (
    warehouseId         INT IDENTITY(1,1),
    warehouseName       VARCHAR(30),    
    PRIMARY KEY (warehouseId)
);

CREATE TABLE shipment (
    shipmentId          INT IDENTITY(1,1),
    shipmentDate        DATETIME,   
    shipmentDesc        VARCHAR(100),   
    warehouseId         INT, 
    PRIMARY KEY (shipmentId),
    FOREIGN KEY (warehouseId) REFERENCES warehouse(warehouseId)
        ON UPDATE CASCADE ON DELETE NO ACTION
);

CREATE TABLE ordersummary (
    orderId             INT IDENTITY(1,1),
    orderDate           DATETIME,
    totalAmount         DECIMAL(10,2),
    shiptoAddress       VARCHAR(50),
    shiptoCity          VARCHAR(40),
    shiptoState         VARCHAR(20),
    shiptoPostalCode    VARCHAR(20),
    shiptoCountry       VARCHAR(40),
    customerId          INT,
	shipmentId			INT,
    paymentMethodId     INT NOT NULL,
    PRIMARY KEY (orderId),
    FOREIGN KEY (customerId) REFERENCES customer(customerid)
        ON UPDATE CASCADE ON DELETE CASCADE,
	FOREIGN KEY (shipmentId) REFERENCES shipment(shipmentId)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT FK_ordersummary_paymentmethod FOREIGN KEY (paymentMethodId) REFERENCES paymentmethod(paymentMethodId)
        ON UPDATE NO ACTION ON DELETE NO ACTION 		
);

CREATE TABLE category (
    categoryId          INT IDENTITY(1,1),
    categoryName        VARCHAR(50),    
    PRIMARY KEY (categoryId)
);

CREATE TABLE product (
    productId           INT IDENTITY(1,1),
    productName         VARCHAR(40),
    productPrice        DECIMAL(10,2),
    productImageURL     VARCHAR(100),
    productImage        VARBINARY(MAX),
    productDesc         VARCHAR(1000),
    categoryId          INT,
    PRIMARY KEY (productId),
    FOREIGN KEY (categoryId) REFERENCES category(categoryId)
);

CREATE TABLE orderproduct (
    orderId             INT,
    productId           INT,
    quantity            INT,
    price               DECIMAL(10,2),  
    PRIMARY KEY (orderId, productId),
    FOREIGN KEY (orderId) REFERENCES ordersummary(orderId)
        ON UPDATE CASCADE ON DELETE NO ACTION,
    FOREIGN KEY (productId) REFERENCES product(productId)
        ON UPDATE CASCADE ON DELETE NO ACTION
);

CREATE TABLE incart (
    customerId             INT,
    productId           INT,
    quantity            INT,
    price               DECIMAL(10,2),  
    PRIMARY KEY (customerId, productId),
    FOREIGN KEY (customerId) REFERENCES customer(customerId)
        ON UPDATE CASCADE ON DELETE NO ACTION,
    FOREIGN KEY (productId) REFERENCES product(productId)
        ON UPDATE CASCADE ON DELETE NO ACTION
);


CREATE TABLE productinventory ( 
    productId           INT,
    warehouseId         INT,
    quantity            INT,
    price               DECIMAL(10,2),  
    PRIMARY KEY (productId, warehouseId),   
    FOREIGN KEY (productId) REFERENCES product(productId)
        ON UPDATE CASCADE ON DELETE NO ACTION,
    FOREIGN KEY (warehouseId) REFERENCES warehouse(warehouseId)
        ON UPDATE CASCADE ON DELETE NO ACTION
);

CREATE TABLE review (
    reviewId            INT IDENTITY(1,1),
    reviewRating        INT,
    reviewDate          DATETIME,   
    customerId          INT,
    productId           INT,
    reviewComment       VARCHAR(1000),          
    PRIMARY KEY (reviewId),
    FOREIGN KEY (customerId) REFERENCES customer(customerId)
        ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY (productId) REFERENCES product(productId)
        ON UPDATE CASCADE ON DELETE CASCADE
);
GO

-- Load parent entities first; all IDENTITY values start at one.











