SELECT (SELECT COUNT(*) FROM dbo.customer) AS customers,
       (SELECT COUNT(*) FROM dbo.product) AS products,
       (SELECT COUNT(*) FROM dbo.ordersummary) AS orders,
       (SELECT COUNT(*) FROM dbo.orderproduct) AS orderLines,
       (SELECT COUNT(*) FROM dbo.review) AS reviews;
GO
